/// <summary>
/// Game Plugin Main Entry
/// </summary>
public class GamePlugin : XPlugin, IUIEventSender
{
    /// <summary>
    /// Install the plugin
    /// </summary>
    /// <returns></returns>
    public override bool Install()
    {
        InstallSdkAPI();
        InstallNetRpc();
        InstallUISystem();

        return true;
    }

    /// <summary>
    /// Uninstall the plugin
    /// </summary>
    public override void Uninstall()
    {
        UninstallNetRpc();
        UninstallSdkAPI();
    }

    /// <summary>
    /// Startup the plugin
    /// </summary>
    /// <returns></returns>
    public override bool Startup()
    {
        TryLoadAsyncConfiyFiles(() => {
            InstallEntitys();
            InstallSystems();
        });

        return true;
    }

    /// <summary>Forward widget activation through this plugin's event dispatcher.</summary>
    /// <param name="widget">The activated widget.</param>
    public void OnWidgetOpened(IWidget widget)
    {
        DispatchEvent(new WidgetOpenedEvent { data = new WidgetOpened { widget = widget } });
    }

    /// <summary>Forward the start of widget closing through the game event pipeline.</summary>
    /// <param name="widget">The widget beginning its close sequence.</param>
    public void OnWidgetClosing(IWidget widget)
    {
        DispatchEvent(new WidgetClosingEvent { data = new WidgetClosing { widget = widget } });
    }

    /// <summary>
    /// Install game systems
    /// </summary>
    private void InstallSystems()
    {
        Assembly assembly = Assembly.GetExecutingAssembly();
        foreach (var it in Excel.functionSystemConfig)
        {
            if (it.Value.InstallOnStartup != 0)
            {
                var type = assembly.GetType(it.Value.ClassType);
                if (type != null)
                    Load(type);
            }
        }
    }

    /// <summary>
    /// Uninstall game systems
    /// </summary>
    private void UninstallSystems()
    {
        UnloadAll();
    }

    /// <summary>
    /// Update the plugin
    /// </summary>
    /// <param name="deltaTime"></param>
    public override void Update(float deltaTime)
    {
        // update netrpc
        XNetRpc.Update(deltaTime);

        // update entity dispatcher, fire all entity in queue, notify all listener        
        XEntityManager.GetSingleton().Update(Time.deltaTime);

        // call base update, remove modules
        base.Update(deltaTime);
    }

    /// <summary>
    /// Shutdown the plugin
    /// </summary>
    public override void Shutdown()
    {
        UninstallUISystem();
        UninstallSystems();
        UninstallEntitys();
    }

    /// <summary>
    /// Install NetRpc
    /// </summary>
    private void InstallNetRpc() 
    {
        object[] protocols = new object[] {
            new Rpc()
        };
        
        XNetRpc.Startup(protocols,
            new XNetInternalParser(), XRpcSessionFlag.Http);
    }

    /// <summary>
    /// Uninstall NetRpc
    /// </summary>
    private void UninstallNetRpc()
    {
        XNetRpc.Shutdown();
    }

    /// <summary>
    /// install all entity factorys
    /// </summary>
    private void InstallEntitys()
    {
        List<System.Type> autoInstallEntityTypes = new List<System.Type>();

        Assembly assembly = Assembly.GetExecutingAssembly();
        foreach (var type in assembly.GetTypes())
        {
            var attrs = type.GetCustomAttributes(true);
            foreach (var attr in attrs)
            {
                if (attr is Initialize ii)
                {
                    if (ii.InstallType == InstallType.Startup)
                        autoInstallEntityTypes.Add(type);
                }
            }
        }

        // start entity manager, set entity data syncer
        XEntityManager.GetSingleton().Startup(autoInstallEntityTypes);
    }

    /// <summary>
    /// uninstall all entity factorys
    /// </summary>
    private void UninstallEntitys()
    {
        XEntityManager.GetSingleton().Shutdown();
    }

    /// <summary>
    /// Install product API
    /// </summary>
    /// <exception cref="System.NullReferenceException"></exception>
    private void InstallSdkAPI()
    {
        var conf = XApp.GetSingleton().GetAppConfigure();
        if (!conf)
            throw new System.NullReferenceException();

        // register product api, the app sdk will call product api to get the product info,
        // and the tracking api will call product api to get the product info when tracking events, so register product api before tracking api
        var productAPI = new InternalProductAPI(conf.versionAPI, conf.appId);
        XAppProduct.GetSingleton().RegisterAPI(productAPI);

        // tracking api depends on product api, so register it after product api
        var trackingAPI = new InternalTrackingAPI(conf);
        XAppTracking.GetSingleton().RegisterAPI(trackingAPI);

        // activity api depends on product api, so register it after product api
        var activityAPI = new InternalActivityAPI(conf);
        XAppActivity.GetSingleton().RegisterAPI(activityAPI);

        // email api depends on product api, so register it after product api
        var emailAPI = new InternalEmailAPI(conf);
        XAppEmail.GetSingleton().RegisterAPI(emailAPI);
    }

    /// <summary>
    /// Uninstall product API
    /// </summary>
    private void UninstallSdkAPI()
    {
        XAppProduct.GetSingleton().ClearAPI();
        XAppTracking.GetSingleton().ClearAPI();
        XAppActivity.GetSingleton().ClearAPI();
        XAppEmail.GetSingleton().ClearAPI();
    }

    /// <summary>
    /// install ui system
    /// </summary>
    private void InstallUISystem()
    {
        UISystem.GetSingleton().Startup(new ResourceConfigure() {
            loader = new UIResourceLoader(),
            cacher = new UIDefaultCacher(),
            eventSenders = new List<IUIEventSender> { this }
        });

        UISystem.GetSingleton().RegisterSyncActions(new System.Type[] {
            typeof(SyncFancyView),
            typeof(SyncFancyJumpTo),
            typeof(SyncFancyScrollTo),
            typeof(SyncFancyClick),
            typeof(SyncFancyAnimatorView),
            typeof(SyncFancyAnimatorClick),
            typeof(SyncFancyGridScrollView),
            typeof(SyncFancyGridClick)
        });
    }

    /// <summary>
    /// uninstall ui system
    /// </summary>
    private void UninstallUISystem()
    {
        UISystem.GetSingleton().Shutdown();
    }

    /// <summary>
    /// Load configuration files asynchronously
    /// </summary>
    /// <param name="complete"></param>
    /// <returns></returns>
    private bool TryLoadAsyncConfiyFiles(System.Action complete)
    {
        var conf = XApp.GetSingleton().GetAppConfigure();
        if (!conf)
            return false;

        Assembly assembly = Assembly.GetExecutingAssembly();
        if (conf.bundleSource == AppBundleSource.Local)
        {
#if UNITY_EDITOR
            LoadAsyncConfiyDirectory<TextAsset>(conf.cfgBundle, (assets) => {
                if (ReadConfigFiles(assembly, assets))
                    complete?.Invoke();
            });
#endif
        }
        else
        {
            XRes.LoadBundleAsync(conf.cfgBundle, (bundle) => {
                var assets = bundle.LoadAllAssets();
                if (assets.Length > 0)
                {
                    if (ReadConfigFiles(assembly, assets))
                        complete?.Invoke();
                }
            });
        }

        return true;
    }

    /// <summary>
    /// Read configuration files
    /// </summary>
    /// <param name="assembly"></param>
    /// <param name="assets"></param>
    /// <returns></returns>
    private bool ReadConfigFiles(Assembly assembly, Object[] assets)
    {
        if (!TryGetExcelFields(out var fields))
            return false;

        for (int idx = 0; idx < assets.Length; idx++)
        {
            if (assets[idx] is TextAsset asset)
            {
                var text = System.Text.Encoding.UTF8.GetString(asset.bytes);
                if (!string.IsNullOrEmpty(text))
                {
                    var name = GetConfigTypeName(asset.name);

                    var type = assembly.GetType(name);
                    if (type != null)
                    {
                        IConfigData configData = (IConfigData)JsonConvert.DeserializeObject(text, type);
                        if (fields.TryGetValue(configData.GetName(), out var value))
                        {
                            var datas = configData.GetData();
                            value.SetValue(null, datas);
#if UNITY_EDITOR
                            Debug.Log($"[{Time.frameCount}] Load excel config file {configData.GetName()} done");
#endif
                        }
                    }
                }
            }
        }

        System.GC.Collect();

#if UNITY_EDITOR
        Debug.Log($"[{Time.frameCount}] Load excel config file finished");
#endif
        return true;
    }

    /// <summary>
    /// Get excel fields
    /// </summary>
    /// <param name="fields"></param>
    /// <returns></returns>
    private bool TryGetExcelFields(out Dictionary<string, FieldInfo> fields)
    {
        fields = new Dictionary<string, FieldInfo>();

        System.Type excelType = typeof(Excel);
        foreach (FieldInfo fiedlInfo in excelType.GetFields())
        {
            if (fiedlInfo.IsPublic && fiedlInfo.IsStatic && fiedlInfo.IsInitOnly)
                fields.Add(fiedlInfo.Name, fiedlInfo);
        }

        return true;
    }

    /// <summary>
    /// Get configuration type name
    /// </summary>
    /// <param name="name"></param>
    /// <returns></returns>
    private string GetConfigTypeName(string name)
    {
        return $"Config.{name}";
    }

#if UNITY_EDITOR
    /// <summary>
    /// From directory value configuration file
    /// </summary>
    /// <typeparam name="T"></typeparam>
    /// <param name="path"></param>
    /// <param name="complete"></param>
    private void LoadAsyncConfiyDirectory<T>(string path, System.Action<T[]> complete) where T : Object
    {
        if (Directory.Exists(path))
        {
            List<T> assets = new List<T>();

            var files = AssetDatabase.FindAssets("t:" + typeof(T).Name, new string[] { path });
            foreach (var file in files)
            {
                var assetPath = AssetDatabase.GUIDToAssetPath(file);
                if (!string.IsNullOrEmpty(assetPath))
                {
                    var asset = AssetDatabase.LoadAssetAtPath<T>(assetPath);
                    if (asset)
                        assets.Add(asset);
                }
            }

            complete?.Invoke(assets.ToArray());
        }
    }
#endif

    /// <summary>
    /// Rewrite module loading to achieve RPC protocol registration
    /// </summary>
    /// <param name="type"></param>
    /// <returns></returns>
    public override XEventModule Load(System.Type type)
    {
        if (!FunctionManagerAccess.CanActivate(type))
            return null;

        if (!modules.TryGetValue(type.Name, out var module))
        {
            if (TryGetFunctionSystem(type, out var functionSystem))
            {
                module = (XEventModule)System.Activator.CreateInstance(type);
                module.SetDispatcher(this);

                if (module.Install())
                {
                    XNetRpc.RegisterProtocol(module);
                    if (functionSystem.Active != 0)
                        module.Active();
                }

#if UNITY_EDITOR
                Debug.Log($"[{Time.frameCount}] Load system {type.Name} done");
#endif

                modules.Add(type.Name, module);
            }
        }
        else
        {
            module.Active();
        }

        return module;
    }

    /// <summary>
    /// Rewrite module loading to achieve RPC protocol unregistration
    /// </summary>
    /// <param name="type"></param>
    public override void Unload(System.Type type)
    {
        if (modules.TryGetValue(type.Name, out XEventModule module))
        {
            module.Detive();
            module.Uninstall();

#if UNITY_EDITOR
            Debug.Log($"[{Time.frameCount}] Unload system {type.Name} done");
#endif
            XNetRpc.UnregisterProtocol(module);

            removes.Enqueue(type.Name);
        }
    }

    /// <summary>
    /// Unload all modules
    /// </summary>
    public override void UnloadAll()
    {
        foreach (var it in modules)
        {
            // unregister rpc protocol
            XNetRpc.UnregisterProtocol(it.Value);
            
            // destroy module
            it.Value.Detive();
            it.Value.Uninstall();

#if UNITY_EDITOR
            Debug.Log($"[{Time.frameCount}] Unload module {it.Key}");
#endif
        }

        modules.Clear();
    }

    /// <summary>
    /// Try get function system by type
    /// </summary>
    /// <param name="type"></param>
    /// <param name="functionSystem"></param>
    /// <returns></returns>
    /// <exception cref="System.NullReferenceException"></exception>
    private bool TryGetFunctionSystem(System.Type type, out Config.FunctionSystem functionSystem)
    {
        foreach (var it in Excel.functionSystemConfig)
        {
            if (it.Value.ClassType == type.Name)
            {
                functionSystem = it.Value;
                return true;
            }
        }

        throw new System.NullReferenceException($"Can't find function system {type.Name}");
    }
}

using Oathx.Core;
using Oathx.Entity;
using System.Collections;

/// <summary>
/// Requests system loading and activation through MasterSystem.
/// </summary>
public class SystemActive : IEvent
{
    /// <summary>
    /// Runtime system type to activate.
    /// </summary>
    public System.Type type { get; set; }

    /// <summary>
    /// Optional action after the system activation step completes.
    /// </summary>
    public System.Action complete { get; set; }
}

/// <summary>
/// Requests system deactivation and unloading through MasterSystem.
/// </summary>
public class SystemDetive : IEvent
{
    /// <summary>
    /// Runtime system type to unload.
    /// </summary>
    public System.Type type { get; set; }

    /// <summary>
    /// Optional action after the system unloading step completes.
    /// </summary>
    public System.Action complete { get; set; }
}

/// <summary>
/// Local login success notification that permits game startup.
/// </summary>
public class LoginSucceed : IEvent
{
    /// <summary>
    /// Player identifier supplied by the local caller.
    /// </summary>
    public int pid 
    { get; set; }
}

/// <summary>
/// Local login failure notification.
/// </summary>
public class LoginFailure : IEvent
{
    /// <summary>
    /// Player identifier supplied by the local caller.
    /// </summary>
    public int code
    { get; set; }
}

/// <summary>
/// Coordinates local player persistence and business system startup.
/// </summary>
public class MasterSystem : RuntimeSystem
{
    /// <summary>
    /// Subscribe to local login success without starting Home.
    /// </summary>
    /// <returns>True after registering the local login handler.</returns>
    public override bool OnActive()
    {
        Subscribe<LoginSucceed>(OnLoginSucceed);
        Subscribe<SystemActive>(OnSystemActive);
        Subscribe<SystemDetive>(OnSystemDetive);
        Subscribe<HomeEntryRequested>(OnHomeEntryRequested);
        Subscribe<FunctionOpenChanged>(OnFunctionChanged);

        return true;
    }

    /// <summary>
    /// Release local event subscriptions and unload Home.
    /// </summary>
    public override void OnDetive()
    {
        UnsubscribeAll();

        Unload();
    }

    /// <summary>
    /// Restore local data or persist initial values before starting business systems.
    /// </summary>
    /// <returns>True when local player data is ready.</returns>
    public bool Load()
    {
        if (!IsActive())
            return false;

        if (!XEntityManager.GetSingleton().TryGetEntity(nameof(MasterEntity), out var entity)
            || !(entity is MasterEntity master))
            return false;

        bool ready = master.ExistsSerializeFile()
            ? master.Deserialize()
            : !string.IsNullOrEmpty(master.Serialize());
        if (!ready)
            return false;

        return true;
    }

    /// <summary>
    /// Unload Home, including during deactivation.
    /// </summary>
    /// <returns>True after requesting Home removal from the dispatcher.</returns>
    public bool Unload()
    {
        dispatcher.Unload(typeof(ShopSystem));
        dispatcher.Unload(typeof(NoticeSystem));
        dispatcher.Unload(typeof(FightSystem));
        dispatcher.Unload(typeof(HomeSystem));

        return true;
    }

    /// <summary>
    /// Persist the current local player data without contacting a server.
    /// </summary>
    /// <returns>True when the local archive has been written.</returns>
    public bool Save()
    {
        if (!IsActive())
            return false;

        if (!XEntityManager.GetSingleton().TryGetEntity(nameof(MasterEntity), out var entity)
            || !(entity is MasterEntity master))
            return false;

        return !string.IsNullOrEmpty(master.Serialize());
    }

    /// <summary>
    /// Load and activate a requested business system.
    /// </summary>
    /// <param name="data">Target system and optional completion action.</param>
    private void OnSystemActive(SystemActive data)
    {
        if (IsActive() && IsSystemType(data.type) && FunctionManagerAccess.CanActivate(data.type))
            XCoroutine.Run(ActivateSystem(data));
    }

    /// <summary>Route the reference Home mall entry through the system coordinator.</summary>
    /// <param name="data">Home navigation request.</param>
    private void OnHomeEntryRequested(HomeEntryRequested data)
    {
        if (IsActive() && data.entry == HomeEntry.Shop)
            OnSystemActive(new SystemActive { type = typeof(ShopSystem) });
    }

    /// <summary>
    /// Wait until event dispatch has finished before changing the system registry.
    /// </summary>
    /// <param name="data">Target system and optional completion action.</param>
    /// <returns>The deferred activation sequence.</returns>
    private IEnumerator ActivateSystem(SystemActive data)
    {
        yield return null;

        if (IsActive() && FunctionManagerAccess.CanActivate(data.type))
            LoadSystem(data.type, data.complete);
    }

    /// <summary>
    /// Unload a requested business system and its dependent pages.
    /// </summary>
    /// <param name="data">Target system and optional completion action.</param>
    private void OnSystemDetive(SystemDetive data)
    {
        if (IsActive() && IsSystemType(data.type))
        {
            if (data.type == typeof(LoginSystem))
                dispatcher.Unload(typeof(NoticeSystem));

            UnloadSystem(data.type, data.complete);
        }
    }

    /// <summary>Close a business system when its configured gate becomes unavailable.</summary>
    /// <param name="data">Calculated availability transition.</param>
    private void OnFunctionChanged(FunctionOpenChanged data)
    {
        if (!data.opened && Config.Excel.functionSystemConfig.TryGetValue(data.id, out var row))
        {
            var type = FunctionManagerAccess.ResolveType(row);
            if (IsSystemType(type) && type != typeof(FunctionManagerSystem) && type != typeof(RedDotSystem))
                XCoroutine.Run(CloseUnavailable(type));
        }
    }

    /// <summary>Defer registry changes and reject stale close messages.</summary>
    /// <param name="type">Business system to close.</param>
    /// <returns>The deferred close sequence.</returns>
    private IEnumerator CloseUnavailable(System.Type type)
    {
        yield return null;

        if (IsActive() && !FunctionManagerAccess.CanActivate(type))
            UnloadSystem(type, null);
    }

    /// <summary>
    /// Reject invalid targets and requests to replace the lifecycle coordinator.
    /// </summary>
    /// <param name="type">Requested system type.</param>
    /// <returns>True for a concrete business runtime system.</returns>
    private bool IsSystemType(System.Type type)
    {
        return type != null && type != typeof(MasterSystem) && !type.IsAbstract
            && typeof(RuntimeSystem).IsAssignableFrom(type);
    }

    /// <summary>
    /// Prepare local player data and start Home after local login succeeds.
    /// </summary>
    /// <param name="data">Local login success notification.</param>
    private void OnLoginSucceed(LoginSucceed data)
    {
        if (Load())
        {
            Launch();
        }
    }

    /// <summary>
    /// Unload login and request Home startup.
    /// </summary>
    /// <returns>True when the transition has been requested.</returns>
    private bool Launch()
    {
        if (!IsActive())
            return false;

        dispatcher.Unload(typeof(NoticeSystem));

        UnloadSystem(typeof(LoginSystem), () => {
            if (IsActive())
            {
                LoadSystem(typeof(HomeSystem));
            }
        });

        return true;
    }
}

using System.Collections;
using UnityEngine;
using Oathx.Core;

/// <summary>
/// runtime logic system
/// </summary>
public abstract class RuntimeSystem : XEventModule
{
    /// <summary>
    /// load system
    /// </summary>
    /// <param name="type"></param>
    /// <param name="complete"></param>
    public virtual void LoadSystem(System.Type type, System.Action complete=null)
    {
        XCoroutine.Run(DoLoadAsync(type, complete));
    }

    /// <summary>
    /// do load async
    /// </summary>
    /// <param name="type"></param>
    /// <param name="complete"></param>
    /// <returns></returns>
    private IEnumerator DoLoadAsync(System.Type type, System.Action complete)
    {
        var module = dispatcher.Load(type);
        if (module != null && !module.IsActive())
            module.Active();

        yield return new WaitForEndOfFrame();

        complete?.Invoke();
    }

    /// <summary>
    /// unload system
    /// </summary>
    /// <param name="type"></param>
    /// <param name="complete"></param>
    public void UnloadSystem(System.Type type, System.Action complete)
    {
        XCoroutine.Run(DoUnloadAsync(type, complete));
    }

    /// <summary>
    /// do unload async
    /// </summary>
    /// <param name="type"></param>
    /// <param name="complete"></param>
    /// <returns></returns>
    IEnumerator DoUnloadAsync(System.Type type, System.Action complete)
    {
        dispatcher.Unload(type);
        yield return new WaitForEndOfFrame();
        complete?.Invoke();
    }
}

